const crypto = require('crypto');

// Pega aquí el token real de Pucelo Bot solo dentro de este nodo de n8n.
const BOT_TOKEN = String(
  $vars.TELEGRAM_BOT_TOKEN
  ?? $env.TELEGRAM_BOT_TOKEN
  ?? "",
).trim();

if (!BOT_TOKEN) {
  throw new Error("Falta configurar TELEGRAM_BOT_TOKEN en n8n.");
}
const CATEGORIES = new Set(['Hogar', 'Muebles', 'Electrodomésticos', 'Infantil', 'Ropa', 'Libros', 'Música y cine', 'Tecnología', 'Móviles y telefonía', 'Informática', 'Deportes y ocio', 'Bicicletas', 'Juegos y videojuegos', 'Manualidades y coleccionismo', 'Jardín y bricolaje', 'Otros']);
const CONDITIONS = new Set(['Como nuevo', 'Bueno', 'Aceptable', 'Roto']);
const NEIGHBORHOODS = new Set([
  'Arcas Reales',
  'Arturo Eyries',
  'Barrio España',
  'Batallas',
  'Belén - Pilarica',
  'Campo Grande',
  'Caño Argales',
  'Circular',
  'Ciudad de la Comunicación',
  'Coto de Simancas',
  'Covaresa',
  'Cuatro de Marzo',
  'Delicias - Arco de Ladrillo',
  'Delicias - Canterac',
  'El Berrocal',
  'El Peral',
  'El Pinar',
  'Girón',
  'Hospital',
  'Huerta del Rey',
  'La Antigua - Santa Cruz',
  'La Farola',
  'La Overuela',
  'La Rubia',
  'La Victoria',
  'Las Flores',
  'Las Villas - Valparaíso',
  'Pajarillos Altos',
  'Pajarillos Bajos',
  'Parque Alameda - Paula López',
  'Parquesol',
  'Pilarica - Los Santos',
  'Pinar de Jalón',
  'Plaza de Toros',
  'Plaza España',
  'Plaza Mayor',
  'Polígono Argales',
  'Polígono Industrial la Mora',
  'Polígono San Cristóbal',
  'Puente Duero',
  'Puente Jardín',
  'Rondilla',
  'San Isidro',
  'San Pablo - San Nicolás',
  'San Pedro Regalado',
  'Soto de Medinilla',
  'Urbanización El Pichón',
  'Urbanización El Plantío',
  'Urbanización Entrepinos',
  'Urbanización Las Aceñas',
  'Vadillos',
  'Villa del Prado',
]);

function result(json) {
  return [{ json }];
}

function invalid(error) {
  return result({ ok: false, valid: false, error });
}

function parseQueryString(value) {
  const fields = {};

  try {
    for (const part of String(value).split('&')) {
      const separator = part.indexOf('=');
      if (separator < 0) continue;
      const key = decodeURIComponent(part.slice(0, separator).replace(/\+/g, ' '));
      const fieldValue = decodeURIComponent(part.slice(separator + 1).replace(/\+/g, ' '));
      fields[key] = fieldValue;
    }
  } catch {
    return null;
  }

  return fields;
}

const input = $input.first()?.json ?? {};
let body = input.body ?? input;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    return invalid('invalid_json');
  }
}

const initData = typeof body.initData === 'string' ? body.initData.trim() : '';
if (!initData) return invalid('telegram_init_data_missing');

const fields = parseQueryString(initData);
if (!fields) return invalid('telegram_init_data_malformed');

const receivedHash = fields.hash ?? '';
const authDate = Number(fields.auth_date);
if (!/^[a-f0-9]{64}$/i.test(receivedHash) || !Number.isInteger(authDate)) {
  return invalid('telegram_init_data_invalid');
}

const now = Math.floor(Date.now() / 1000);
if (authDate > now + 60 || now - authDate > 86400) return invalid('telegram_init_data_expired');

const dataCheckString = Object.keys(fields)
  .filter((key) => key !== 'hash')
  .sort()
  .map((key) => `${key}=${fields[key]}`)
  .join('\n');

const secretKey = crypto.createHmac('sha256', 'WebAppData').update(BOT_TOKEN).digest();
const expectedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');
const received = Buffer.from(receivedHash, 'hex');
const expected = Buffer.from(expectedHash, 'hex');
if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
  return invalid('telegram_identity_invalid');
}

let user;
try {
  user = JSON.parse(fields.user ?? '{}');
} catch {
  return invalid('telegram_user_invalid');
}
if (!user || !Number.isSafeInteger(user.id)) return invalid('telegram_user_invalid');

const item = body.item && typeof body.item === 'object' ? body.item : {};
const title = typeof item.title === 'string' ? item.title.trim() : '';
const category = typeof item.category === 'string' ? item.category.trim() : '';
const zone = typeof item.zone === 'string' ? item.zone.trim() : '';
const condition = typeof item.condition === 'string' ? item.condition.trim() : '';
const description = typeof item.description === 'string' ? item.description.trim() : '';
const durationDays = Number(item.duration_days ?? 14);

if (title.length < 3 || title.length > 80) return invalid('title_invalid');
if (!CATEGORIES.has(category)) return invalid('category_invalid');
if (!NEIGHBORHOODS.has(zone)) return invalid('zone_invalid');
if (!CONDITIONS.has(condition)) return invalid('condition_invalid');
if (description.length > 600) return invalid('description_too_long');
if (![7, 14, 30].includes(durationDays)) return invalid('duration_invalid');

const displayName = [user.first_name, user.last_name]
  .filter((value) => typeof value === 'string' && value.trim())
  .join(' ')
  .trim()
  .slice(0, 120) || 'Vecindad';
const telegramId = String(user.id);
const expiresAt = new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000).toISOString();

return result({
  ok: true,
  valid: true,
  title,
  description,
  category,
  zone,
  condition,
  status: 'available',
  expires_at: expiresAt,
  owner_telegram_id: telegramId,
  owner_display_name: displayName,
  owner_username: typeof user.username === 'string' ? user.username : '',
  interest_count: 0,
  favorite_count: 0,
});

const crypto = require('crypto');
const input = $input.first()?.json ?? {};
if (input.valid !== true) return [{ json: input }];

// Identificador público opaco: nunca incluye el Telegram user ID.
const publicItemId = crypto.randomBytes(6).toString('base64url');
return [{ json: { ...input, public_id: publicItemId, item_id: publicItemId } }];

const validated = $input.first()?.json ?? {};
if (validated.valid !== true) return [{ json: validated }];

const webhook = $('Webhook').first()?.json ?? {};
let body = webhook.body ?? webhook;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { return [{ json: { ok: false, valid: false, error: 'invalid_json' } }]; }
}

const consent = body.consent && typeof body.consent === 'object' ? body.consent : {};
const consentVersion = typeof consent.version === 'string' ? consent.version.trim() : '';
if (consent.accepted !== true) return [{ json: { ok: false, valid: false, error: 'consent_required' } }];
if (consentVersion !== 'sv-publish-2026-08-17-v3') return [{ json: { ok: false, valid: false, error: 'consent_version_invalid' } }];

return [{ json: { ...validated, consent_accepted: true, consent_version: consentVersion, consent_at: new Date().toISOString() } }];

const created = $input.first()?.json ?? {};
const fields = created.fields ?? created;
const publicId = fields.public_id ?? fields['item-id'] ?? created.public_id ?? created['item-id'] ?? '';
return [{
  json: {
    ok: true,
    public_id: publicId,
    item_id: publicId,
    title: fields.title ?? created.title ?? '',
    status: fields.status ?? created.status ?? 'available',
    message: 'Publicado correctamente',
  },
}];
